"""Publish a release for the current main commit.

Version rules:
- manifest.json version higher than the last vX.Y.Z tag (or no tag yet):
  that version is released as is (manual bump wins);
- otherwise it is bumped from the commits since the last tag:
  major if a commit says "BREAKING CHANGE" or uses "type!:",
  minor if a commit subject starts with "feat",
  patch otherwise.

Then: manifest.json + card version updated, CHANGELOG.md prepended, commit
"chore(release): vX.Y.Z", tag, push, GitHub release with the same notes.

Usage: python .github/scripts/release.py [--dry-run]
"""

from __future__ import annotations

import datetime as dt
import json
import os
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
MANIFEST = ROOT / "custom_components" / "suivi_colis" / "manifest.json"
INIT = ROOT / "custom_components" / "suivi_colis" / "__init__.py"
CARD = ROOT / "custom_components" / "suivi_colis" / "www" / "suivi-colis-card.js"
CHANGELOG = ROOT / "CHANGELOG.md"
RELEASE_PREFIX = "chore(release):"
MAX_COMMITS = 30


def run(*args: str, check: bool = True) -> str:
    result = subprocess.run(args, cwd=ROOT, capture_output=True, text=True, encoding="utf-8")
    if check and result.returncode != 0:
        sys.exit(f"{' '.join(args)} failed:\n{result.stderr}")
    return result.stdout.strip()


def parse(version: str) -> tuple[int, int, int]:
    match = re.fullmatch(r"v?(\d+)\.(\d+)\.(\d+)", version.strip())
    if not match:
        sys.exit(f"Invalid version: {version!r}")
    return tuple(int(p) for p in match.groups())  # type: ignore[return-value]


def fmt(version: tuple[int, int, int]) -> str:
    return ".".join(map(str, version))


def last_tag() -> str | None:
    tags = run("git", "tag", "--list", "v*", "--sort=-v:refname").splitlines()
    tags = [t for t in tags if re.fullmatch(r"v\d+\.\d+\.\d+", t)]
    return tags[0] if tags else None


def commits_since(tag: str | None) -> list[tuple[str, str, str]]:
    """(sha, subject, body) of non-release commits since tag, oldest first."""
    rev = f"{tag}..HEAD" if tag else "HEAD"
    raw = run("git", "log", "--reverse", "--format=%H%x1f%s%x1f%b%x1e", rev)
    commits = []
    for entry in raw.split("\x1e"):
        if not entry.strip():
            continue
        sha, subject, body = (entry.strip("\n").split("\x1f") + ["", ""])[:3]
        if not subject.startswith(RELEASE_PREFIX):
            commits.append((sha, subject, body))
    return commits


def bump_level(commits: list[tuple[str, str, str]]) -> str:
    level = "patch"
    for _, subject, body in commits:
        if "BREAKING CHANGE" in body or re.match(r"^\w+(\([^)]*\))?!:", subject):
            return "major"
        if re.match(r"^feat(\([^)]*\))?:", subject, re.IGNORECASE):
            level = "minor"
    return level


def next_version(manifest_version: str, tag: str | None, commits) -> str:
    current = parse(manifest_version)
    if tag is None or current > parse(tag):
        return fmt(current)
    major, minor, patch = parse(tag)
    level = bump_level(commits)
    if level == "major":
        return fmt((major + 1, 0, 0))
    if level == "minor":
        return fmt((major, minor + 1, 0))
    return fmt((major, minor, patch + 1))


def github_notes(version: str, tag: str | None) -> str:
    """Notes generated by GitHub from merged PRs ('' if unavailable)."""
    repo = os.environ.get("GITHUB_REPOSITORY")
    if not repo or not os.environ.get("GH_TOKEN"):
        return ""
    args = [
        "gh", "api", f"repos/{repo}/releases/generate-notes",
        "-f", f"tag_name=v{version}",
        "-f", f"target_commitish={run('git', 'rev-parse', 'HEAD')}",
    ]
    if tag:
        args += ["-f", f"previous_tag_name={tag}"]
    out = run(*args, check=False)
    try:
        return json.loads(out).get("body", "").strip()
    except ValueError:
        return ""


def build_notes(version: str, tag: str | None, commits) -> str:
    notes = github_notes(version, tag)
    if "* " in notes:  # GitHub found merged PRs
        return notes
    # No PR (direct pushes): list the commits instead
    lines = ["## Changements", ""]
    shown = commits[-MAX_COMMITS:]  # newest ones (the first release has the whole history)
    for sha, subject, _ in reversed(shown):
        lines.append(f"- {subject} ({sha[:7]})")
    if len(commits) > len(shown):
        lines.append(f"- … et {len(commits) - len(shown)} commits plus anciens")
    if notes:  # keep GitHub's "Full Changelog" compare link
        lines += ["", notes]
    return "\n".join(lines)


def update_files(version: str, notes: str) -> None:
    manifest = json.loads(MANIFEST.read_text(encoding="utf-8"))
    manifest["version"] = version
    MANIFEST.write_text(json.dumps(manifest, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")

    # Card cache-busting versions follow the integration version
    for path, pattern in (
        (INIT, r'CARD_JS_VERSION = "[^"]*"'),
        (CARD, r'const CARD_VERSION = "[^"]*"'),
    ):
        text = path.read_text(encoding="utf-8")
        new = re.sub(pattern, pattern.split(" = ")[0] + f' = "{version}"', text, count=1)
        path.write_text(new, encoding="utf-8")

    today = dt.date.today().isoformat()
    previous = CHANGELOG.read_text(encoding="utf-8") if CHANGELOG.exists() else ""
    header = "# Changelog\n\n"
    body = previous[len(header):] if previous.startswith(header) else previous
    # Demote the notes' headings under the version heading
    section_notes = re.sub(r"^(#+) ", r"#\1 ", notes, flags=re.MULTILINE)
    CHANGELOG.write_text(
        f"{header}## v{version} — {today}\n\n{section_notes.strip()}\n\n{body.lstrip()}".rstrip() + "\n",
        encoding="utf-8",
    )


def main() -> None:
    sys.stdout.reconfigure(encoding="utf-8")
    dry_run = "--dry-run" in sys.argv
    tag = last_tag()
    commits = commits_since(tag)
    if tag and not commits:
        print(f"Nothing to release since {tag}.")
        return

    manifest_version = json.loads(MANIFEST.read_text(encoding="utf-8"))["version"]
    version = next_version(manifest_version, tag, commits)
    if run("git", "tag", "--list", f"v{version}"):
        sys.exit(f"Tag v{version} already exists.")
    notes = build_notes(version, tag, commits)

    print(f"Last tag: {tag or '-'} | manifest: {manifest_version} | release: v{version}")
    print(notes)
    if dry_run:
        return

    update_files(version, notes)
    run("git", "add", str(MANIFEST), str(INIT), str(CARD), str(CHANGELOG))
    run("git", "commit", "-m", f"{RELEASE_PREFIX} v{version}")
    run("git", "tag", "-a", f"v{version}", "-m", f"v{version}")
    branch = os.environ.get("GITHUB_REF_NAME", "main")
    run("git", "push", "origin", f"HEAD:{branch}")
    run("git", "push", "origin", f"v{version}")

    notes_file = ROOT / ".release-notes.md"
    notes_file.write_text(notes + "\n", encoding="utf-8")
    run("gh", "release", "create", f"v{version}", "--title", f"v{version}",
        "--notes-file", str(notes_file), "--verify-tag")
    notes_file.unlink()
    print(f"Released v{version}")


if __name__ == "__main__":
    main()
